const r = $('Find Issues').first().json.report || {};
const overdue = Array.isArray(r.overdue) ? r.overdue : [];
const stale = Array.isArray(r.stale_delivered) ? r.stale_delivered : [];
const invited = Array.isArray(r.invited_no_response) ? r.invited_no_response : [];
const total = r.total_issues || 0;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null ? Number(n).toFixed(0) + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }

const rowsOverdue = overdue.map(a => `<tr style="background:${a.days_overdue > 14 ? '#fee' : '#fff8e0'}">
  <td>${esc(a.collaborator_name)} <small style="color:#666">(${esc(a.specialty || '')})</small></td>
  <td>${esc(a.project_name)}</td>
  <td>${esc(a.role)}</td>
  <td>${esc(a.status)}</td>
  <td>${dateShort(a.deadline)}</td>
  <td style="text-align:right;color:#c00;font-weight:600">+${a.days_overdue}d</td>
  <td style="text-align:right">${money(a.fee_eur)}</td>
</tr>`).join('');

const rowsStale = stale.map(a => `<tr>
  <td>${esc(a.collaborator_name)}</td>
  <td>${esc(a.project_name)}</td>
  <td>${esc(a.role)}</td>
  <td>${dateShort(a.delivered_at)}</td>
  <td style="text-align:right;font-weight:600">${a.days_since_delivery}d</td>
  <td style="text-align:right">${money(a.fee_eur)}</td>
</tr>`).join('');

const rowsInvited = invited.map(a => `<tr>
  <td>${esc(a.collaborator_name)}</td>
  <td>${esc(a.project_name)}</td>
  <td>${esc(a.role)}</td>
  <td>${dateShort(a.invited_at)}</td>
  <td style="text-align:right">${a.days_since_invite}d</td>
</tr>`).join('');

const sections = [];
if (overdue.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Deadline vencido (${overdue.length})</h3><p style="font-size:13px;color:#555">Colaboradores que se comprometieron a entregar y la fecha ya paso. Hay que recordarles o cerrar/cancelar.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">colaborador</th><th align="left">proyecto</th><th align="left">rol</th><th align="left">status</th><th align="left">deadline</th><th align="right">retraso</th><th align="right">honorario</th></tr></thead><tbody>${rowsOverdue}</tbody></table>`);
}
if (stale.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Entregados sin aprobar (${stale.length})</h3><p style="font-size:13px;color:#555">El colaborador ya entrego pero llevas mas de 7 dias sin aprobar. Revisar y marcar approved/rejected_delivery.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">colaborador</th><th align="left">proyecto</th><th align="left">rol</th><th align="left">entregado</th><th align="right">dias</th><th align="right">honorario</th></tr></thead><tbody>${rowsStale}</tbody></table>`);
}
if (invited.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Invitados sin respuesta (${invited.length})</h3><p style="font-size:13px;color:#555">Mas de 5 dias sin que el colaborador haya aceptado/rechazado la invitacion.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">colaborador</th><th align="left">proyecto</th><th align="left">rol</th><th align="left">invitado</th><th align="right">dias</th></tr></thead><tbody>${rowsInvited}</tbody></table>`);
}

const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:780px">
<h2>Colaboradores - revision diaria (${total} pendientes)</h2>
${sections.join('\n')}
<p style="font-size:12px;color:#888;margin-top:24px">cron_collab_review - generado ${new Date().toISOString()}</p>
</div>`;

const subject = `[Collaboradores] ${total} pendientes (${overdue.length} vencidos / ${stale.length} sin aprobar / ${invited.length} sin respuesta)`;

return [{ json: { html, subject, total } }];
